using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad] public static class EconomyOrdersVerification {
  const string Key="EconomyOrdersVerification";
  static double started;static int phase;static List<string> rows=new List<string>();static CampaignHUD hud;static RecoveryPoint city;
  static string Root {get{var path=Path.GetFullPath(Path.Combine(Application.dataPath,"../VerificationOutputs"));Directory.CreateDirectory(path);return path;}}
  static EconomyOrdersVerification(){if(SessionState.GetBool(Key,false)){started=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}}
  public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");SessionState.SetBool(Key,true);started=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
  static void Check(bool ok,string text){if(!ok)throw new Exception(text);rows.Add("PASS "+text);Debug.Log("ECONOMY_PASS "+text);}
  static void Near(float actual,float expected,string text){Check(Mathf.Abs(actual-expected)<=Mathf.Max(.05f,Mathf.Abs(expected)*.00001f),text+" ("+actual+" / "+expected+")");}
  static Button FindButton(string title){return hud.GetComponentsInChildren<Button>(true).First(b=>b.gameObject.activeInHierarchy&&(b.name==title||b.GetComponentInChildren<Text>()!=null&&b.GetComponentInChildren<Text>().text==title));}
  static LocalPrototypeOrders.Waypoint At(RecoveryPoint p){return new LocalPrototypeOrders.Waypoint{city=p};}
  static Vector3 BuildSpot(BattleWorld w,BattleUnit engineer,RecoveryPoint near){
   foreach(var cell in w.territory.AllCells().OrderBy(c=>Vector2.Distance(c.center,near.transform.position)).Take(100)){
    Vector3 p=cell.center;if(Vector2.Distance(p,near.transform.position)<1)continue;var point=new RoadPoint(p.x,p.y);if(!w.setup.freeMarchMap.CanTraverse(point,point,engineer.GetComponent<ArmyRoadMover>().AllowedTerrain))continue;engineer.transform.position=p;w.territory.Resolve();if(w.campaign.CanBuildDepot(engineer,p))return p;
   }throw new Exception("No valid test construction position");
  }
  static void Test(BattleWorld w){
   w.enabled=false;w.GetComponent<BattleAIController>().enabled=false;w.GetComponent<AIBasicCommander>().enabled=false;w.GetComponent<LocalTacticalBattle>().enabled=false;w.fogEnabled=false;w.SetPlayer("A");
   city=w.points.First(p=>p.ownerId=="A"&&!p.isRepairSite);Near(city.resourceStock,100000,"starting city uses new resource scale");Near(w.campaign.logistics.sites[0].stock,2000000,"resource fields use new resource scale");
   foreach(var u in w.units.ToArray()){if(u.Point!=null)u.BeginExit();u.Motor?.Stop();u.transform.position=new Vector3(u.ownerId=="A"?-44:44,-27);}
   var production=w.GetComponent<InfantryProduction>();production.enabled=false;var logistics=w.GetComponent<LogisticsWorld>();var orders=w.GetComponent<LocalPrototypeOrders>();var coordinated=w.GetComponent<LocalCoordinatedOrders>();hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();city.resourceStock=10000000;
   var prices=new Dictionary<UnitRole,float>{{UnitRole.Infantry,10000},{UnitRole.Scout,12000},{UnitRole.Engineer,15000},{UnitRole.MountainInfantry,14000},{UnitRole.Tank,50000},{UnitRole.Artillery,40000},{UnitRole.RocketArtillery,60000},{UnitRole.PersonnelCarrier,20000}};
   foreach(var item in prices)Near(production.Cost(ArmyEchelon.Squad,item.Key),item.Value,item.Key+" squad price");Near(logistics.truckPrefab.GetComponent<TransportTruck>().definition.BuildCost(ArmyEchelon.Squad),20000,"resource truck squad price");
   Check(production.Quote("A",city,ArmyEchelon.Squad,false,1,UnitRole.Scout).allowed,"squad scout can be produced");Check(!production.Quote("A",city,ArmyEchelon.Platoon,false,1,UnitRole.Scout).allowed,"larger scout rejected by production service");
   foreach(var role in new[]{UnitRole.Artillery,UnitRole.RocketArtillery}){Check(production.Quote("A",city,ArmyEchelon.Battalion,false,1,role).allowed,role+" battalion allowed");Check(!production.Quote("A",city,ArmyEchelon.Regiment,false,1,role).allowed,role+" regiment rejected");}
   Check(!production.Quote("A",city,ArmyEchelon.Squad,false,1,UnitRole.Radar).allowed,"radar remains engineer deployed");
   float before=city.resourceStock;Check(production.Queue("A",city,ArmyEchelon.Squad,false,1,UnitRole.Tank),"tank production queues");Near(before-city.resourceStock,50000,"production deducts quoted price once");Check(production.Cancel("A",city),"production cancellation accepted");Near(city.resourceStock,before,"cancel returns exact paid price");
   city.resourceStock=9999;Check(!production.Queue("A",city,ArmyEchelon.Squad,false),"insufficient resources reject production");Near(city.resourceStock,9999,"rejected production spends nothing");city.resourceStock=10000000;
   before=city.resourceStock;Check(logistics.BuildTruckFor("A",city,null,ArmyEchelon.Squad),"resource truck can queue");Near(before-city.resourceStock,20000,"truck uses same currency scale");Check(logistics.CancelBuildFor("A",city),"truck cancellation accepted");Near(city.resourceStock,before,"truck cancellation refunds actual payment");
   var engineer=w.units.First(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Engineer);var spot=BuildSpot(w,engineer,city);var near=w.campaign.CreateDepot(spot+Vector3.up*.7f,"A",19999,false);var enemyDepot=w.campaign.CreateDepot(spot+Vector3.right*.05f,"B",100000,false);
   Check(w.campaign.NearestStorage("A",spot)==near.recovery,"nearest storage ignores closer enemy warehouse");Check(!w.campaign.BuildDepot(engineer,spot).accepted,"poor nearest warehouse blocks construction despite wealthy distant city");Near(near.stock,19999,"rejected construction preserves warehouse stock");Near(city.resourceStock,10000000,"rejected construction never charges distant city");enemyDepot.Remove();
   near.stock=20000;int depots=w.campaign.depots.Count;Check(w.campaign.BuildDepot(engineer,spot).accepted,"exact funds at nearest warehouse permit construction");Near(near.stock,0,"nearest warehouse charged exactly once");Check(w.campaign.depots.Count==depots+1,"one warehouse created after payment");Near(city.resourceStock,10000000,"successful construction does not charge distant city");
   var built=w.campaign.depots.Last();built.stock=30000;near.stock=100000;var truck=w.units.First(u=>u.ownerId=="A"&&u.GetComponent<TransportTruck>()!=null).GetComponent<TransportTruck>();truck.Unit.combatDefinition=UnityEngine.Object.Instantiate(truck.Unit.combatDefinition);truck.Unit.combatDefinition.echelon=ArmyEchelon.Squad;truck.Unit.Restore(truck.Unit.Capacity);truck.SetCargo(0);Near(truck.Capacity,10000,"transport squad carries ten thousand resources");
   truck.transform.position=near.transform.position;Check(orders.StartPatrol(truck.Unit,new[]{At(near.recovery),At(built.recovery)}),"warehouse to warehouse transport starts");float conserved=near.stock+built.stock+truck.Cargo;orders.Tick(5);Near(truck.Cargo,10000,"first storage is loading endpoint; five seconds fills truck");Near(near.stock,90000,"source debited by loaded cargo");
   truck.transform.position=built.transform.position;orders.Tick(3);Near(truck.Cargo,0,"second storage unloads truck within three seconds");Near(built.stock,40000,"destination receives cargo");Near(near.stock+built.stock+truck.Cargo,conserved,"warehouse transfer conserves resources");
   truck.transform.position=near.transform.position;orders.Tick(5);Near(truck.Cargo,10000,"next cycle returns to load at source");built.ownerId="B";orders.Tick(.1f);Check(!orders.IsAssigned(truck.Unit),"captured transport destination cancels task");Near(truck.Cargo,10000,"captured destination preserves cargo");built.ownerId="A";truck.SetCargo(0);
   near.stock=3000;truck.transform.position=near.transform.position;Check(orders.StartPatrol(truck.Unit,new[]{At(near.recovery),At(city)}),"warehouse to city route starts");orders.Tick(5);Near(truck.Cargo,3000,"exhausted source allows partial shipment");truck.transform.position=city.transform.position;before=city.resourceStock;orders.Tick(3);Near(city.resourceStock-before,3000,"city receives partial shipment");Near(near.stock,0,"source cannot go negative");orders.CancelUnit(truck.Unit,true);
   near.stock=0;truck.transform.position=near.transform.position;orders.StartPatrol(truck.Unit,new[]{At(near.recovery),At(city)});orders.Tick(5);Near(truck.Cargo,0,"empty source does not create resources");Check(orders.Status(truck.Unit)=="等待来源补给","empty storage waits for replenishment");orders.CancelUnit(truck.Unit,true);
   var site=w.campaign.logistics.sites[0];truck.transform.position=site.transform.position;truck.SetCargo(0);site.stock=10000;Check(orders.StartPatrol(truck.Unit,new[]{new LocalPrototypeOrders.Waypoint{site=site},At(city)}),"resource field to city route starts");orders.Tick(5);Near(truck.Cargo,10000,"resource field loads without negative stock");Near(site.stock,0,"loading deducts finite resource field stock");orders.CancelUnit(truck.Unit,true);truck.SetCargo(0);
   var selection=w.GetComponent<ArmySelection>();selection.SelectOwned(truck.GetComponent<ArmyRoadMover>());truck.transform.position=near.transform.position;Check(orders.ToggleDraft(LocalPrototypeOrders.DraftKind.Patrol),"first transport setting click enters draft");orders.AddDraft(At(near.recovery));orders.AddDraft(At(city));Check(!orders.IsAssigned(truck.Unit),"draft does not execute before confirmation");Check(orders.ToggleDraft(LocalPrototypeOrders.DraftKind.Patrol)&&!orders.Drafting&&orders.IsAssigned(truck.Unit),"second identical setting click commits transport");orders.CancelUnit(truck.Unit,true);
   var infantry=w.units.First(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry);infantry.transform.position=spot;selection.SelectOwned(infantry.GetComponent<ArmyRoadMover>());
   foreach(var kind in new[]{LocalPrototypeOrders.DraftKind.Road,LocalPrototypeOrders.DraftKind.Straight}){infantry.Motor.Stop();Check(orders.ToggleDraft(kind),kind+" first click enters draft");orders.AddDraft(new LocalPrototypeOrders.Waypoint{position=spot+Vector3.right*.1f});Check(!infantry.Motor.IsMoving,kind+" draft does not move unit");Check(orders.ToggleDraft(kind)&&!orders.Drafting,kind+" repeated click confirms and executes");Check(infantry.Motor.IsMoving,kind+" route executes after confirmation");infantry.Motor.Stop();}
   orders.ToggleDraft(LocalPrototypeOrders.DraftKind.Road);orders.AddDraft(new LocalPrototypeOrders.Waypoint{position=spot+Vector3.right*.1f});orders.CancelDraft();Check(!infantry.Motor.IsMoving&&!orders.Drafting,"cancelled route draft never executes");
   var other=w.units.First(u=>u!=infantry&&u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry);other.transform.position=spot+Vector3.right*.15f;coordinated.BeginPicking(LocalCoordinatedOrders.PickMode.Rotation);coordinated.Pick(infantry);coordinated.Pick(other);Check(!coordinated.InRotation(infantry),"rotation selections wait for confirmation");coordinated.TogglePicking(LocalCoordinatedOrders.PickMode.Rotation);Check(coordinated.InRotation(infantry),"rotation repeated button starts operation");coordinated.CancelRotation(infantry);
   coordinated.BeginPicking(LocalCoordinatedOrders.PickMode.Defense);coordinated.Pick(infantry);coordinated.Pick(other);Check(coordinated.LinkCount(infantry)==0,"defense selections wait for confirmation");coordinated.TogglePicking(LocalCoordinatedOrders.PickMode.Defense);Check(coordinated.LinkCount(infantry)==1,"defense repeated button confirms links");coordinated.CancelDefense(infantry);
   var radarPos=spot+Vector3.left*.7f;engineer.transform.position=radarPos;near.stock=20000;built.stock=20000;var payer=w.campaign.NearestStorage("A",radarPos);payer.resourceStock=20000;Check(RadarInstallation.CanDeploy(w,engineer,radarPos),"radar validates nearest storage funding");before=payer.resourceStock;Check(RadarInstallation.Deploy(w,engineer,radarPos).accepted,"funded radar deploys");Near(before-payer.resourceStock,20000,"radar charges nearest storage once");Check(w.units.Last(u=>u.GetComponent<RadarInstallation>()!=null).combatDefinition.echelon==ArmyEchelon.Squad,"deployed radar has squad echelon");
   hud.SelectBuilding(city);FindButton("建筑与生产").onClick.Invoke();Check(hud.GetComponentsInChildren<Button>(true).Count(b=>b.gameObject.activeInHierarchy&&b.name.StartsWith("生产卡片 "))==9,"production displays nine selectable unit cards");Check(!hud.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="生产设置小面板"&&t.gameObject.activeInHierarchy),"production configuration opens only after choosing unit");
   FindButton("生产卡片 Scout").onClick.Invoke();Check(!FindButton("编制增加").interactable,"scout production plus button disabled at squad");FindButton("返回兵种列表").onClick.Invoke();FindButton("生产卡片 Artillery").onClick.Invoke();for(int i=0;i<3;i++)FindButton("编制增加").onClick.Invoke();Check(!FindButton("编制增加").interactable,"artillery plus stops at battalion");FindButton("编制减少").onClick.Invoke();Check(FindButton("编制增加").interactable,"minus permits returning to lower echelon");
   FindButton("返回兵种列表").onClick.Invoke();FindButton("生产卡片 RocketArtillery").onClick.Invoke();for(int i=0;i<3;i++)FindButton("编制增加").onClick.Invoke();Check(!FindButton("编制增加").interactable,"rocket production plus stops at battalion");FindButton("返回兵种列表").onClick.Invoke();FindButton("生产卡片 Tank").onClick.Invoke();
   city.resourceStock=1000000;hud.RefreshStaffDetails();Canvas.ForceUpdateCanvases();
   Check(hud.GetComponentsInChildren<Transform>(true).Any(t=>t.gameObject.activeInHierarchy&&t.name=="生产设置小面板"),"unit card opens production configuration panel");
   infantry.SetPersonnelExact(infantry.Capacity-1);infantry.transform.position=city.transform.position;infantry.UnderFire=false;Check(infantry.BeginEnter(city),"damaged unit can enter friendly city");Check(infantry.BeginRepair(),"repair can start after currency conversion");before=city.resourceStock;float health=infantry.Personnel;w.Tick(1);Near(before-city.resourceStock,(infantry.Personnel-health)*100,"repair charges actual restored health in new currency");
   Check(hud.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="兵种卡片").All(t=>!t.gameObject.activeInHierarchy),"configuration view avoids overflowing card grid");
   rows.Add("INFO existing regiment artillery assets retained; prices use squad baseline and existing 3.3 cost / 3 time scaling.");
  }
  static void Capture(string file="economy-production-preview.png"){var canvas=hud.GetComponentInParent<Canvas>();var camera=UnityEngine.Object.FindObjectOfType<BattleWorld>().setup.mapCamera;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=5;var rt=new RenderTexture(1280,900,24);camera.targetTexture=rt;Canvas.ForceUpdateCanvases();camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(1280,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1280,900),0,0);texture.Apply();File.WriteAllBytes(Path.Combine(Root,file),texture.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(texture);UnityEngine.Object.DestroyImmediate(rt);}
  static void Poll(){try{if(EditorApplication.timeSinceStartup-started>180)throw new Exception("verification timeout");if(!EditorApplication.isPlaying||Time.time<1)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;if(phase==0){Test(w);phase=1;return;}if(phase++<5)return;if(phase==6){Capture();FindButton("返回兵种列表").onClick.Invoke();return;}if(phase<9)return;Capture("economy-unit-cards-preview.png");Finish(null);}catch(Exception e){Finish(e);}}
  static void Finish(Exception e){if(e!=null){rows.Add("FAIL "+e);Debug.LogException(e);}File.WriteAllLines(Path.Combine(Root,"economy-verification.txt"),rows);SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(e==null?0:1);}
 }
}
